/** Original v2 saved-QC inspection and complete native normalization/PCA/distance checks. */
public final class NfcoreChipseq200QcAuditCli {
    private NfcoreChipseq200QcAuditCli() { }
    static final String ACTION = "Required action: read WARNINGS.md, audit.json, original R_sessionInfo.log, source task logs and every retained process/process.stderr. This is the ChIP-seq2.0.0 saved-QC component only, with zero catalog-tool, biological or whole-paper admission. Original R4.0.3/DESeq2_1.28.0 DDS, RDS and size-factor objects must agree. Native Java checks every ratio factor, normalized cell, all-gene PCA Gram/eigenvalue/orthogonality contract and full Euclidean distance matrix. FeatureCounts assignments and nonlinear VST/rlog remain original upstream methods; no negative-binomial model is refitted. Preserve original row order, IDs, missing/nonfinite values, provider/locale warnings and failures. Source zero-based BED Start is copied unchanged to SAF; inclusive featureCounts Length=End-Start+1 is retained. Source MultiQC heatmap text says rlog even when the actual saved transform is VST; trust the explicit saved-assay metadata, not that caption. SKIP3 means a missing/forbidden exact runtime/image/capability: dependent analysis skipped; perform permitted separate setup or use an allowed environment. FAIL2 means no component result: inspect the named integrity, input, process, capacity or numeric failure, resolve it and retry a NEW path. No imputation, axis-sign repair, reduced matrix or finite estimate is substituted. Cell Ranger remains excluded.";
    private static final Set<String> REQUIRED = Set.of("--engine-result", "--image-set", "--container-home", "--out");
    private static final Set<String> CAPACITIES = Set.of("--wall-seconds", "--address-space-bytes", "--cpu-seconds", "--file-bytes", "--open-files", "--workspace-bytes", "--files", "--processes", "--threads", "--sampled-rss-bytes", "--poll-ms");
    public static void main(String[] args) {
        Path out = null; boolean owned = false;
        try {
            if (args.length == 1 && args[0].equals("--help")) { emit(System.out, "--engine-result COMPLETE_ORIGINAL_V2_RESULT --image-set EXACT_IMAGE_DECLARATION --container-home EXACT_APPTAINER_HOME --out NEW_AUDIT\nOptional explicit capacities: " + CAPACITIES + "\n" + ACTION); return; }
            var options = new LinkedHashMap<String, String>(); for (int i = 0; i < args.length; i += 2) if (i + 1 >= args.length || !(REQUIRED.contains(args[i]) || CAPACITIES.contains(args[i])) || options.putIfAbsent(args[i], args[i + 1]) != null) throw new IOException("Require complete unique saved-QC options; see --help"); if (!options.keySet().containsAll(REQUIRED)) throw new IOException("Declare every saved-QC prerequisite explicitly"); var capacities = limits(options);
            Path selected = Path.of(options.get("--engine-result")).toAbsolutePath().normalize(); out = Path.of(options.get("--out")).toAbsolutePath().normalize(); var verified = NfcoreEngineBundle.verify(selected, () -> { }); Path producer = Path.of(text(object(json(verified.attempt().resolve("session.json"), 67108864)).get("producer_root")));
            if (out.getParent() == null || !out.getParent().toRealPath().equals(out.getParent()) || out.startsWith(selected) || selected.startsWith(out) || out.startsWith(verified.attempt()) || verified.attempt().startsWith(out) || producer.isAbsolute() && (out.startsWith(producer) || producer.startsWith(out))) throw new IOException("Require a NEW canonical audit disjoint from the immutable attempt and original producer"); Files.createDirectory(out); owned = true;
            var data = new NfcoreChipseq200Files(verified); data.verifySource(); var peaks = new NfcoreChipseq200Peaks(data, NfcoreChipseq200Peaks.mappings(data)); var parameters = data.files.parameters();
            if (parameters.containsKey("deseq2_vst") && !(parameters.get("deseq2_vst") instanceof Boolean)) throw new IOException("Require the source Boolean deseq2_vst setting"); String transform = Boolean.FALSE.equals(parameters.get("deseq2_vst")) ? "rlog" : "vst";
            Path declaration = Path.of(options.get("--image-set")).toAbsolutePath().normalize(); Pin declarationPin = pin(declaration, 1048576, () -> { }); Path captured = out.resolve("image-set.json"); Files.copy(declaration, captured); if (!pin(captured, 1048576, () -> { }).equals(declarationPin)) throw new IOException("Image declaration changed during capture");
            Path own = Path.of(NfcoreChipseq200QcAuditCli.class.getProtectionDomain().getCodeSource().getLocation().toURI()); if (!Files.isRegularFile(own) || !own.toString().endsWith(".jar")) throw new NextflowProcess.Unavailable("Use the packaged saved-QC artifact; unbound execution skipped"); Pin ownPin = pin(own, 1000000000L, () -> { });
            NfcoreChipseq200QcRuntime runtime = null; var groups = new ArrayList<Map<String, Object>>(); var omitted = new ArrayList<String>(); var warnings = new ArrayList<String>();
            for (var group : peaks.groups) {
                if (!(group.multipleGroups() && group.replicates())) { if (data.tasks().stream().anyMatch(t -> t.process().endsWith(":DESEQ2_QC") && t.tag().equals(group.antibody()))) throw new IOException("Observed QC task contradicts original group/replicate eligibility"); omitted.add(group.antibody()); continue; }
                if (runtime == null) { runtime = new NfcoreChipseq200QcRuntime(Path.of(options.get("--container-home")).toAbsolutePath().normalize(), captured, Files.createDirectory(out.resolve("original-qc-runtime")), capacities); runtime.health(); }
                String prefix = group.prefix().substring(group.prefix().lastIndexOf('/') + 1), base = group.prefix().substring(0, group.prefix().lastIndexOf('/') + 1) + "deseq2/";
                Path caseRoot = Files.createDirectory(out.resolve("original-qc-runtime/antibody-" + (groups.size() + 1))); Path worker = runtime.inspect(data.files.output(base + prefix + ".dds.RData"), data.files.output(base + prefix + ".rds"), data.files.output(group.prefix() + ".featureCounts.txt"), data.files.output(base + "size_factors/" + prefix + ".size_factors.RData"), transform, caseRoot);
                var groupReport = NfcoreChipseq200QcFiles.audit(data, group, worker, transform); groupReport.put("original_worker_relative_path", out.relativize(worker).toString().replace('\\', '/')); groups.add(groupReport);
                String diagnostics = utf8(bytes(caseRoot.resolve("process/process.stderr"), 16777216)); if (!diagnostics.isBlank()) warnings.add(group.antibody() + " original QC runtime stderr (retained without locale replacement):\n" + diagnostics);
            }
            if (runtime != null) runtime.verify(); var after = NfcoreEngineBundle.verify(selected, () -> { }); if (!after.attempt().equals(verified.attempt()) || !after.manifest().equals(verified.manifest()) || !pin(declaration, 1048576, () -> { }).equals(declarationPin) || !pin(captured, 1048576, () -> { }).equals(declarationPin) || !pin(own, 1000000000L, () -> { }).equals(ownPin)) throw new IOException("Original result, image declaration or implementation changed during complete QC inspection");
            var report = new LinkedHashMap<String, Object>(); report.put("status", "COMPLETE_ORIGINAL_CHIPSEQ200_SAVED_QC_COMPONENT_ONLY"); report.put("original_engine_manifest", verified.manifest()); report.put("antibodies", groups); report.put("source_ineligible_QC_antibodies", omitted); report.put("actual_saved_transform", transform); report.put("warnings", warnings); report.put("process_capacities", capacities); report.put("scientific_result_admitted", false); report.put("nfcore_tool_credit", 0); writeJson(out.resolve("audit.json"), report);
            Files.writeString(out.resolve("WARNINGS.md"), "# Original v2 saved-QC component only\n\n" + ACTION + "\n\n" + String.join("\n\n", warnings) + "\n", StandardCharsets.UTF_8, StandardOpenOption.CREATE_NEW); writeJson(out.resolve("COMPONENT_AUDIT_COMPLETED.json"), Map.of("status", "complete-original-v2-saved-QC-component-only", "audit", pin(out.resolve("audit.json"), 67108864, () -> { }), "scientific_result_admitted", false, "nfcore_tool_credit", 0)); emit(System.out, "Complete original v2 saved QC passed for " + groups.size() + " eligible antibody groups; " + omitted.size() + " source-ineligible branches retained.\n" + ACTION); for (String warning : warnings) emit(System.err, warning);
        } catch (Exception | LinkageError failure) {
            int code = failure instanceof NextflowProcess.Unavailable ? 3 : 2; emit(System.err, (code == 3 ? "SKIP3 ANALYSIS SKIPPED: " : "FAIL2 NO V2 SAVED-QC COMPONENT: ") + failure + "\n" + ACTION);
            if (owned && out != null) try { writeJson(out.resolve("FAILURE.json"), Map.of("status", code == 3 ? "SKIP3" : "FAIL2", "error", failure.toString(), "required_action", ACTION)); Files.writeString(out.resolve("WARNINGS.md"), "# " + (code == 3 ? "SKIP3" : "FAIL2") + "\n\n" + failure + "\n\n" + ACTION + "\n", StandardCharsets.UTF_8, StandardOpenOption.CREATE_NEW); } catch (IOException diagnostic) { emit(System.err, "Retain failed audit; diagnostic write failed: " + diagnostic); } System.exit(code);
        }
    }
    private static long positive(String value, long maximum) throws IOException { try { if (!value.matches("[0-9]+")) throw new NumberFormatException(); long n = Long.parseLong(value); if (n < 1 || n > maximum) throw new NumberFormatException(); return n; } catch (NumberFormatException bad) { throw new IOException("Require exact positive bounded QC capacities", bad); } }
    private static long option(Map<String, String> o, String key, String fallback, long max) throws IOException { return positive(o.getOrDefault(key, fallback), max); }
    private static NextflowProcess.Limits limits(Map<String, String> o) throws IOException { return new NextflowProcess.Limits(option(o,"--wall-seconds","1800",604800)*1000,option(o,"--address-space-bytes","68719476736",1099511627776L),option(o,"--cpu-seconds","1800",604800),option(o,"--file-bytes","1000000000",1000000000000L),(int)option(o,"--open-files","4096",1048576),option(o,"--workspace-bytes","17179869184",1000000000000L),(int)option(o,"--files","100000",1000000),(int)option(o,"--processes","128",4096),(int)option(o,"--threads","4096",1048576),option(o,"--sampled-rss-bytes","17179869184",1099511627776L),(int)option(o,"--poll-ms","100",1000)); }
    private static void emit(java.io.PrintStream output, String text) { output.writeBytes((text + "\n").getBytes(StandardCharsets.UTF_8)); }
}
